import sys, libcst
data = open(sys.argv[1], 'rb').read()
try:
    libcst.parse_module(data)
except Exception:
    sys.exit(1)
depth = worst = 0
for byte in data:
    if byte in b'([{':
        depth += 1
        if depth > worst:
            worst = depth
    elif byte in b')]}' and depth:
        depth -= 1
sys.exit(0 if worst >= 400 else 1)
